import json,numpy as np
from scipy.spatial.transform import Rotation
S=json.load(open('/app/output/spec.json'))
J=S['proprio']['joints']; P=np.array(S['proprio']['position_m']); AX=np.array(S['proprio']['axis'])
L=S['links']; parents=dict(zip(L['names'],L['parent']))
# one joint per moving link in the specification
JL=dict(zip(L['names'][1:],J))

def fk(q):
    tf={'pelvis':np.eye(4)}
    for link in L['names'][1:]:
        j=J.index(JL[link]); R=Rotation.from_rotvec(AX[j]*q[j]).as_matrix(); T=np.eye(4);T[:3,:3]=R;T[:3,3]=P[j]-R@P[j]
        tf[link]=tf[parents[link]]@T
    return tf

def point(T,p):return T[:3,:3]@p+T[:3,3]

def camera_project(p):
    c=S['cameras']['room_camera']['pose'];d=np.array(p)-c['position_m']; f=128/np.tan(np.pi/8)
    return np.array([128+f*np.dot(d,c['right'])/np.dot(d,c['forward']),128-f*np.dot(d,c['up'])/np.dot(d,c['forward'])])
if __name__=='__main__':
    m=json.load(open('/app/output/initial/meta.json'));q=np.array(m['proprio']['now'][:69]);tf=fk(q)
    for n in ['left_ankle_link','lh_palm','torso_link']:
        p=point(tf[n], L['com_m'][L['names'].index(n)]);print(n,p)
    g=np.array(m['proprio']['now'][-3:]);R=Rotation.align_vectors([[0,0,-1]],[g])[0].as_matrix();print('R',R)
    foot=point(tf['left_ankle_link'],[.04,.203,-1.065]);z=-(R@foot)[2];print('baseheight',z)
    for n in ['pelvis','lh_palm','left_ankle_link']:
        p=R@point(tf[n],L['com_m'][L['names'].index(n)])+[0,0,z];print(n,p,camera_project(p))
    c=S['cameras']['room_camera']['pose'];f=128/np.tan(np.pi/8)
    for label,uv in [('slide handle',(63,105)),('double handle',(107,137)),('drawer handle',(112,161)),('top',(94,73))]:
        ray=np.array(c['forward'])+(uv[0]-128)/f*np.array(c['right'])-(uv[1]-128)/f*np.array(c['up'])
        for x in [.65,.75,.85]:
            p=np.array(c['position_m'])+ray*((x-c['position_m'][0])/ray[0]);print(label,x,p)
PY
